#pragma once
// TITAN-VIBE (VIBE_ONLY=1): entry points of the TITAN modules this build
// leaves out.
//
// TITAN-VIBE compiles the TITAN engine unchanged and leaves out the energy,
// solvation, kinetics and analysis modules. The engine still names their entry
// points (it decides at run time which modules a run uses), so this build
// defines them in absent_entry_points.cpp (generated by
// tools/vibe_only/generate_absent_entry_points.py) and, for the few the engine
// calls on every run, in disabled_modules.cpp. option_allowlist.cpp refuses
// every option of the missing modules, so a VIBE run never reaches absent().

namespace titan_vibe_only {

// Stops the program with an internal error naming `entry_point`.
[[noreturn]] void absent(const char *entry_point) noexcept;

} // namespace titan_vibe_only
